grammar oracle.parameters.matrix.falsecall.Language hidden(WS)
generate model "urn:intersect:parameter-matrix:false_call"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: child=Node<false>; Node<Flag>: <Flag> a=ID | <!Flag> b=ID;
terminal ID: ('z'..'a')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;
terminal ANY_OTHER: .;

